{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = set(node_map.keys())
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        if n['parent'] is None:
            continue
        if any(c in retained for c in children.get(nid, [])):
            continue
        # Check that all required symbols remain after removal
        ok = True
        for sym in required_symbols:
            count = sum(1 for rid in retained if rid != nid and node_map[rid]['symbol'] == sym)
            if count == 0:
                ok = False
                break
        if not ok:
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"}
